import{_ as e,o as d,c as o,a3 as r}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Live Chat — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Live Chat — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/live-chat-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Live Chat — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/live-chat-production-readiness"}]]},"headers":[],"relativePath":"deployment/live-chat-production-readiness.md","filePath":"deployment/live-chat-production-readiness.md","lastUpdated":1790204574000}'),a={name:"deployment/live-chat-production-readiness.md"};function i(s,t,n,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="live-chat-—-production-readiness-audit" tabindex="-1">Live Chat — Production Readiness Audit <a class="header-anchor" href="#live-chat-—-production-readiness-audit" aria-label="Permalink to &quot;Live Chat — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-17</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — production-readiness remediations closed (catalog <strong>1.0.1</strong>); complete migrate + staging smoke before production opt-in embeds</td></tr><tr><td><strong>Scope</strong></td><td>Free Communication Marketplace module <code>live-chat</code> catalog <strong>1.0.1</strong> (not default-included)</td></tr><tr><td><strong>Companion</strong></td><td><a href="./live-chat">Live Chat deployment</a> · <a href="/developer-guide/live-chat">Developer guide</a> · <a href="/user-guide/live-chat">User guide</a> · <a href="/api/tenant-v1-live-chat">API</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Live Chat ships catalog, tenant inbox, public widget script (CORS-open for credential-less embeds), soft Lead link, public DTO hardening, session revoke on key regen, Pest + Playwright coverage.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Catalog free opt-in <code>live-chat</code> <strong>1.0.1</strong> (not default-included)</td><td><strong>Pass</strong></td></tr><tr><td>Permissions <code>view</code> / <code>reply</code> / <code>assign</code> / <code>manage</code> + default roles</td><td><strong>Pass</strong></td></tr><tr><td>Session token SHA-256; CSRF exempt; inactive widget 404</td><td><strong>Pass</strong></td></tr><tr><td>Entitlement check on public + tenant paths; tenant isolation</td><td><strong>Pass</strong></td></tr><tr><td>Soft Leads (no hard module dep)</td><td><strong>Pass</strong></td></tr><tr><td>Rate limits <code>live-chat-widget</code> + tighter <code>live-chat-widget-session</code></td><td><strong>Pass</strong></td></tr><tr><td>CORS for credential-less third-party embeds (<code>LiveChatPublicCors</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Public responses strip agent/Lead/IP PII</td><td><strong>Pass</strong></td></tr><tr><td>Regenerate key invalidates visitor sessions</td><td><strong>Pass</strong></td></tr><tr><td>Session TTL (7 days) + scheduled visitor purge (90 days)</td><td><strong>Pass</strong></td></tr><tr><td>Module cancel/deactivate flips widgets inactive</td><td><strong>Pass</strong></td></tr><tr><td>PlatformAudit + <code>LogsActivity</code>; <code>UtcDateTime</code> on <code>last_message_at</code></td><td><strong>Pass</strong></td></tr><tr><td>Pest public entitlement / CORS / IDOR / regen / TTL / 413</td><td><strong>Pass</strong></td></tr><tr><td>Playwright <code>test:e2e:live-chat</code> human workflow</td><td><strong>Pass</strong></td></tr><tr><td>Docs hubs (user / developer / API / deploy / entitlements / roadmap)</td><td><strong>Pass</strong></td></tr></tbody></table><p><strong>Go / No-Go:</strong> <strong>Go</strong> for merge after CI green. Ops must migrate through <strong>1.0.1</strong> and complete staging smoke (including a third-party Origin embed) before customer traffic.</p><hr><h2 id="locked-decision-matrix" tabindex="-1">Locked-decision matrix <a class="header-anchor" href="#locked-decision-matrix" aria-label="Permalink to &quot;Locked-decision matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Backend</th><th>Frontend</th><th>Docs</th></tr></thead><tbody><tr><td>Free Communication opt-in (not default-included)</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Soft Lead link (no hard module dep)</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Agent inbox (WhatsApp-style), not Team Chat</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Media + Help Desk escalate</td><td>Pass</td><td>Pass</td><td>Pass (invoice share / bots still deferred)</td></tr><tr><td>Visitor Echo (realtime)</td><td>Pass</td><td>Pass</td><td>Pass</td></tr><tr><td>Captcha / Turnstile (beyond throttle + TTL)</td><td>Deferred</td><td>Deferred</td><td>Deferred</td></tr><tr><td>Mobile shell</td><td>Out of scope</td><td>Out of scope</td><td>Out of scope</td></tr></tbody></table><hr><h2 id="catalog-version-path" tabindex="-1">Catalog version path <a class="header-anchor" href="#catalog-version-path" aria-label="Permalink to &quot;Catalog version path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Migration</th><th>Effect</th></tr></thead><tbody><tr><td><code>2026_09_17_003600</code></td><td>Tables: widgets, visitors, conversations, messages</td></tr><tr><td><code>2026_09_17_003610</code></td><td>Register <code>live-chat</code> <strong>1.0.0</strong> (free, not default-included)</td></tr><tr><td><code>2026_09_17_003620</code></td><td>Permissions + default role grants</td></tr><tr><td><code>2026_09_17_003630</code></td><td>Catalog <strong>1.0.0 → 1.0.1</strong> (production-readiness remediations)</td></tr><tr><td><code>2026_09_17_003700</code></td><td>Expand schema + catalog <strong>1.0.1 → 1.3.0</strong></td></tr></tbody></table><p>Production: <strong>migrate only</strong>. <code>CatalogSeeder</code> seeds <code>live-chat</code> <strong>1.3.0</strong> for local fresh seeds.</p><hr><h2 id="findings-2026-09-17-remediations" tabindex="-1">Findings (2026-09-17 remediations) <a class="header-anchor" href="#findings-2026-09-17-remediations" aria-label="Permalink to &quot;Findings (2026-09-17 remediations)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>LC-01</td><td>Critical</td><td>CORS pinned to SPA — embeds failed</td><td><code>LiveChatPublicCors</code> reflects Origin for <code>api/public/live-chat/*</code>; Pest OPTIONS + GET</td></tr><tr><td>LC-02</td><td>High</td><td>Public APIs leaked agent/Lead/IP PII</td><td><code>LiveChatPublicConversationResource</code> / <code>LiveChatPublicMessageResource</code>; no sender load on visitor poll</td></tr><tr><td>LC-03</td><td>High</td><td>Key regen left sessions valid</td><td><code>revokeVisitorSessions()</code> on regenerate + deactivate</td></tr><tr><td>LC-04</td><td>High</td><td>No public entitlement Pest</td><td>Public bootstrap 403 after cancel + widgets inactive</td></tr><tr><td>LC-05</td><td>Medium</td><td>Throttle-only; no session expiry</td><td>7-day session TTL; tighter session-create limiter (10/min)</td></tr><tr><td>LC-06</td><td>Medium</td><td>No visitor retention</td><td><code>live-chat:purge-visitors --days=90</code> daily</td></tr><tr><td>LC-07</td><td>Medium</td><td>No audit / activity log</td><td><code>PlatformAuditService</code> + <code>LogsActivity</code> on widget/conversation</td></tr><tr><td>LC-08</td><td>Medium</td><td><code>last_message_at</code> default datetime</td><td><code>UtcDateTime</code> cast</td></tr><tr><td>LC-09</td><td>Medium</td><td>Cancel left widgets active</td><td><code>deactivateLiveChatIfNeeded</code> on cancel/deactivate</td></tr><tr><td>LC-10</td><td>Medium</td><td>Silent query failures</td><td>Frontend <code>ErrorState</code> + retry on widget / list / messages</td></tr><tr><td>LC-11</td><td>Medium</td><td>Pest security gaps</td><td>CORS, IDOR, regen, TTL, 413, public entitlement</td></tr><tr><td>LC-12</td><td>Low</td><td>MaxBodyBytes only on some POSTs</td><td>All public POSTs</td></tr></tbody></table><h3 id="ops-not-code-blockers" tabindex="-1">Ops (not code blockers) <a class="header-anchor" href="#ops-not-code-blockers" aria-label="Permalink to &quot;Ops (not code blockers)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Owner</th></tr></thead><tbody><tr><td>O1</td><td>Medium</td><td>Companion CI Quality Gates on Live Chat PRs</td><td>Eng</td></tr><tr><td>O2</td><td>Low</td><td>Serve <code>public/widgets/live-chat.js</code> from API host (or CDN); APP_URL reachable</td><td>Ops</td></tr><tr><td>O3</td><td>Low</td><td>Ensure Forge scheduler runs <code>live-chat:purge-visitors</code></td><td>Ops</td></tr></tbody></table><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li><strong>Backend</strong> — migrate through <code>2026_09_17_003630</code>; scheduler includes <code>live-chat:purge-visitors</code></li><li><strong>Frontend</strong> — SPA with query error states</li><li><strong>Docs</strong> — this readiness page + <a href="./live-chat">live-chat</a></li><li>Staging smoke below before production opt-in traffic</li></ol><p>Suggested merge order: <strong>Backend → Frontend → Docs</strong>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrations through <code>2026_09_17_003630</code> (catalog <strong>1.0.1</strong>)</td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Catalog <code>live-chat</code> = <strong>1.0.1</strong>; Marketplace install (not default-included)</td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td>APP_URL reachable; widget script served; public CORS verified from foreign Origin</td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Rate limiters <code>live-chat-widget</code> + <code>live-chat-widget-session</code> active</td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td>Scheduler: <code>live-chat:purge-visitors --days=90</code></td><td>Ops</td><td>☐</td></tr><tr><td>6</td><td>Pest <code>LiveChatModuleTest</code> green</td><td>Eng</td><td>☐</td></tr><tr><td>7</td><td>Playwright <code>test:e2e:live-chat</code> green</td><td>QA</td><td>☐</td></tr><tr><td>8</td><td>Leads entitled only if soft-link tested</td><td>Ops</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace → install <strong>Live Chat</strong> (free)</li><li>Staff with <code>live-chat.view</code> sees <code>/live-chat</code>; without module → gate</li><li>Widget settings: greeting, prechat required, save; copy embed snippet</li><li>From a <strong>third-party origin</strong> (or browser DevTools Origin), bootstrap + session + message succeed (CORS)</li><li>Confirm public message/conversation JSON has <strong>no</strong> assignee, lead, visitor IP, or sender email</li><li>Agent reply / claim / close; inbound notification → deep-link</li><li>Soft-link / unlink Lead when Leads entitled; hide when not</li><li>Regenerate public key → old embed key fails; old visitor sessions rejected</li><li>Deactivate widget / uninstall module → public API 404/403; widgets inactive after cancel</li><li>Prechat validation when required; empty reply blocked; oversized body → 413</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep additive migrations</td></tr><tr><td>Module disable</td><td>Marketplace uninstall / cancel</td></tr><tr><td>Schema</td><td>Do <strong>not</strong> roll back Live Chat migrations without a data plan</td></tr></tbody></table><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Throttle denials on <code>live-chat-widget</code> / <code>live-chat-widget-session</code></li><li>Public 401/403/404 rates on <code>/api/public/live-chat/*</code></li><li>Notification type <code>live-chat.inbound</code></li><li><code>live-chat:purge-visitors</code> daily output / failures</li><li>Application logs for tenancy init failures on public paths</li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Eng</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>QA</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>Ops</td><td></td><td></td><td>☐ Ready</td></tr></tbody></table><p><strong>Release decision:</strong> <strong>Go</strong> — merge companions after CI green; complete staging smoke and migrate to <strong>1.0.1</strong> before production opt-in embeds.</p>',39)])])}const p=e(a,[["render",i]]);export{u as __pageData,p as default};
